"""How do eyay (and other top teams) set a and b, relative to the proven t brackets?

Per recent game: feedback.digest gives every team's issued charge a per item, their accept
limit as an interval [b_lo, b_hi), and t brackets. We compare a/t and b/t behaviour for
eyay, OPUSMOPUS, Non Deterministic, Codacabana vs us (actual submissions).
"""
import json
import math
import statistics
import sys
from pathlib import Path

ROOT = Path(r"c:\Users\Admin\Desktop\TUM\8.Semester\Hackathon\EHL-Hackathon-template-repo")
sys.path.insert(0, str(ROOT))
from c2f.feedback import digest  # noqa: E402

GAMES = [34, 35, 36, 37, 38, 39, 40, 41]
TEAMS = ["eyay", "OPUSMOPUS", "Non Deterministic", "Codacabana", "AsianSuperNerds"]

stats = {t: {"a_over_tlo": [], "a_fair": 0, "a_fraud": 0, "a_open": 0, "a_zero": 0,
             "b_over_tlo": [], "rej_fair": 0, "acc_fair": 0, "acc_fraud": 0, "rej_fraud": 0,
             "income_lb": 0.0} for t in TEAMS}

for g in GAMES:
    try:
        d = digest(g)
    except Exception as e:
        print(f"game {g}: digest failed ({e.__class__.__name__})", file=sys.stderr)
        continue
    # merge cached tighter truth
    tp = ROOT / "runs" / f"truth_game_{g:02d}.json"
    tr = json.loads(tp.read_text()) if tp.exists() else {}
    for i in d["items"]:
        t_lo, t_hi = d["t_lo"][i], d["t_hi"][i]
        v = tr.get(str(i))
        if v:
            t_lo = max(t_lo, float(v.get("t_lo") or 0.0))
            if v.get("t_hi") is not None:
                t_hi = min(t_hi, float(v["t_hi"]))
        for team in TEAMS:
            if team not in d["teams"]:
                continue
            s = stats[team]
            a = d["issued"].get(team, {}).get(i)
            if a is not None:
                if a <= 0:
                    s["a_zero"] += 1
                else:
                    if t_lo > 0:
                        s["a_over_tlo"].append(a / t_lo)
                    if a <= t_lo + 1e-9:
                        s["a_fair"] += 1
                        s["income_lb"] += a * (len(d["teams"]) - 1)
                    elif t_hi != float("inf") and a >= t_hi - 1e-9:
                        s["a_fraud"] += 1
                    else:
                        s["a_open"] += 1
            b_lo = d["b_lo"].get(team, {}).get(i, 0.0)
            b_hi = d["b_hi"].get(team, {}).get(i, float("inf"))
            b_mid = b_lo if b_hi == float("inf") else 0.5 * (b_lo + b_hi)
            if t_lo > 0 and b_mid > 0:
                s["b_over_tlo"].append(b_mid / t_lo)
            # behaviour on proven charges from others
            for j in d["teams"]:
                if j == team:
                    continue
                aj = d["issued"].get(j, {}).get(i)
                if not aj or aj <= 0:
                    continue
                fair = True if aj <= t_lo + 1e-9 else (False if (t_hi != float("inf") and aj >= t_hi - 1e-9) else None)
                acc = True if aj <= b_lo + 1e-9 else (False if aj >= b_hi - 1e-9 else None)
                if fair is True and acc is True:
                    s["acc_fair"] += 1
                elif fair is True and acc is False:
                    s["rej_fair"] += 1
                elif fair is False and acc is True:
